import{b as t,O as s,g as e,j as i}from"./chunks/framework.DcaUmd3X.js";const g=JSON.parse('{"title":"解决合并冲突","description":"","frontmatter":{},"headers":[],"relativePath":"git/branch/merge-conflict/index.md","filePath":"Git操作手册/3.分支管理/02.解决合并冲突.md","lastUpdated":1782199931000}'),n={name:"git/branch/merge-conflict/index.md"};function l(o,a,p,c,d,h){return s(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="解决合并冲突" tabindex="-1">解决合并冲突 <a class="header-anchor" href="#解决合并冲突" aria-label="Permalink to &quot;解决合并冲突&quot;">​</a></h1><blockquote><p>冲突是怎么产生的 / 怎么解决 / 怎么避免</p></blockquote><h2 id="冲突是怎么产生的" tabindex="-1">冲突是怎么产生的 <a class="header-anchor" href="#冲突是怎么产生的" aria-label="Permalink to &quot;冲突是怎么产生的&quot;">​</a></h2><p>两个人改了同一个文件的同一行，Git 不知道该用谁的版本——这就是冲突。</p><p>具体来说，当两个分支对<strong>同一个文件的同一区域</strong>做了不同的修改，Git 合并时就会停下来，把决定权交给你：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你改的：  const title = &quot;我的项目&quot;;</span></span>
<span class="line"><span>同事改的：const title = &quot;新项目名称&quot;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Git： 🤷 我该用哪个？</span></span></code></pre></div><h2 id="冲突长什么样" tabindex="-1">冲突长什么样 <a class="header-anchor" href="#冲突长什么样" aria-label="Permalink to &quot;冲突长什么样&quot;">​</a></h2><p>假设你在 <code>master</code> 和 <code>feature</code> 两个分支上都改了 <code>app.js</code> 的同一行，执行合并：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> master</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature</span></span></code></pre></div><p>Git 输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Auto-merging app.js</span></span>
<span class="line"><span>CONFLICT (content): Merge conflict in app.js</span></span>
<span class="line"><span>Automatic merge failed; fix conflicts and then commit the result.</span></span></code></pre></div><p>打开 <code>app.js</code>，冲突区域被 Git 标记了出来：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;&lt;&lt;&lt;&lt;&lt;&lt; HEAD</span></span>
<span class="line"><span>const title = &quot;我的版本&quot;;</span></span>
<span class="line"><span>=======</span></span>
<span class="line"><span>const title = &quot;feature 分支的版本&quot;;</span></span>
<span class="line"><span>&gt;&gt;&gt;&gt;&gt;&gt;&gt; feature</span></span></code></pre></div><p>三个标记的含义：</p><ul><li><code>&lt;&lt;&lt;&lt;&lt;&lt;&lt; HEAD</code> — 当前分支（你所在的分支）的版本</li><li><code>=======</code> — 分隔线</li><li><code>&gt;&gt;&gt;&gt;&gt;&gt;&gt; feature</code> — 被合并分支的版本</li></ul><p>你需要在这两个版本中选择一个——或者手动改写成新的内容。</p><h2 id="怎么解决" tabindex="-1">怎么解决 <a class="header-anchor" href="#怎么解决" aria-label="Permalink to &quot;怎么解决&quot;">​</a></h2><h3 id="方式一-手动编辑" tabindex="-1">方式一：手动编辑 <a class="header-anchor" href="#方式一-手动编辑" aria-label="Permalink to &quot;方式一：手动编辑&quot;">​</a></h3><p>直接打开冲突文件，删除标记符号（<code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</code>、<code>=======</code>、<code>&gt;&gt;&gt;&gt;&gt;&gt;&gt;</code>），保留你想要的内容。改完后：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app.js</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 告诉 Git 冲突已解决</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # 完成合并提交，不需要 -m，Git 会用默认合并信息</span></span></code></pre></div><h3 id="方式二-用-vs-code-一键解决" tabindex="-1">方式二：用 VS Code 一键解决 <a class="header-anchor" href="#方式二-用-vs-code-一键解决" aria-label="Permalink to &quot;方式二：用 VS Code 一键解决&quot;">​</a></h3><p>VS Code 会自动识别冲突区域，在代码上方显示三个按钮：</p><ul><li><strong>Accept Current Change</strong> — 保留当前分支的版本</li><li><strong>Accept Incoming Change</strong> — 用被合并分支的版本</li><li><strong>Accept Both Changes</strong> — 两个都保留</li></ul><p>点击选一个就行，比手动删标记快得多。解决完后在源代码管理面板点 <code>+</code>（相当于 <code>git add</code>），然后提交。</p><h3 id="反悔了怎么办" tabindex="-1">反悔了怎么办 <a class="header-anchor" href="#反悔了怎么办" aria-label="Permalink to &quot;反悔了怎么办&quot;">​</a></h3><p>冲突解到一半发现搞错了方向，不想继续了：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --abort</span></span></code></pre></div><p>回到合并之前的状态，就像什么都没发生过。</p><h2 id="怎么减少冲突" tabindex="-1">怎么减少冲突 <a class="header-anchor" href="#怎么减少冲突" aria-label="Permalink to &quot;怎么减少冲突&quot;">​</a></h2><p>冲突无法完全避免，但可以减少：</p><ol><li><strong>拉取再改</strong> — 每天开工先 <code>git pull</code>，保持本地和远程同步</li><li><strong>小步提交</strong> — 不要攒了三天改动再 merge，改一点合一点</li><li><strong>同文件少同时改</strong> — 团队成员尽量不碰同一个文件的同一区域</li><li><strong>沟通</strong> — 改公共模块之前先说一声</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>冲突不可怕，怕的是不知道这些标记什么意思：</p><ol><li><strong>冲突 = Git 选不了</strong> — 两个人改了同一行，Git 把决定权交给你</li><li><strong>标记读得懂</strong> — <code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</code> 是你、<code>&gt;&gt;&gt;&gt;&gt;&gt;&gt;</code> 是对方、<code>=======</code> 是分界线</li><li><strong>解决就三步</strong> — 编辑文件选一个版本 → <code>git add</code> → <code>git commit</code></li><li><strong>反悔有 <code>--abort</code></strong> — 不想解了直接取消合并</li></ol><h2 id="自主练习" tabindex="-1">自主练习 <a class="header-anchor" href="#自主练习" aria-label="Permalink to &quot;自主练习&quot;">​</a></h2><ol><li>创建两个分支，分别修改同一个文件的同一行，合并制造一个冲突</li><li>用文本编辑器手动解决冲突（删标记、选内容），然后提交</li><li>再次制造冲突，用 VS Code 的&quot;Accept Current / Incoming Change&quot;按钮解决</li><li>合并过程中用 <code>git merge --abort</code> 取消，确认仓库恢复原样</li></ol>`,36)])])}const u=t(n,[["render",l]]);export{g as __pageData,u as default};
